"""Layer 15 MLP down_proj component 4288: a sparse "verb-chain linker" detector.

What it does: it is near zero almost everywhere, and jumps up on the word that
joins one action to the next, when the next word will be another verb or an
infinitive/purpose phrase:
  - "and" / "or" joining a second verb or noun phrase, strongest after a noun or verb
    ("... the reactor [and] keep it", "... the code changes [and] identify ...");
  - "to" in purpose and infinitive clauses ("in order [to] make", "to [see] if");
  - connectors like "by", "how", "that", "as" that open an action clause;
  - a few words that introduce an elaboration or a result: "make", "sure", "ensure",
    "including", "particularly", "especially" (very high).
It is negative after "or" and "but" (noun or clause coordination).

The program is a small rule table; it does not model the context beyond the one
previous word. On the eval rows it explains under 1% of the variance (r about 0.11):
the component's large spikes depend on context that no token rule here can see.
A per-token table would add a little (about 3% in-sample on training rows), but
only by memorising which words spike, which explains nothing.
"""
import wordnet

READS = ()

BOOST = {"make", "makes", "making", "sure", "ensure", "ensuring", "including",
         "particularly", "especially", "particular"}
LINKS = {"by", "how", "that", "which", "as", "so", "such"}
NEGATIVE = {"or", "but"}


def is_noun_or_verb(word):
    tags = wordnet.parts_of_speech(word)
    return "noun" in tags or "verb" in tags


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position == 0:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    if word == "and":
        return carry, 0.7 if before.isalpha() and is_noun_or_verb(before) else 0.1
    if word in BOOST:
        return carry, 1.5
    if word == "to":
        return carry, 0.1
    if word in LINKS:
        return carry, 0.2
    if word in NEGATIVE:
        return carry, -0.3
    return carry, 0.0

"""Layer 15 MLP hidden unit 4291, as read through down_proj component 4291.

This component is almost exactly one MLP neuron: its input weight is 0.92 on
hidden unit 4291 (about 70% of its input energy), so its activation is that
neuron's value times about 1.05. Negative values push the residual stream toward
words of fault, blame and suspicion (the unembedding of its output direction,
taken with a minus sign), and the strongest negative values come on words about
blaming, accusing and attributing, then on words about believing, thinking,
interpreting and imagining, and more weakly on "seem" and "appear". Everything
else is predicted as 0. Most of the component's variance is diffuse, depends on
the surrounding context, and is not captured by word identity.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

BLAME = {"blame", "blamed", "blames", "blaming", "accuse", "accused", "accuses",
         "accusing", "accusation", "accusations", "scapegoat"}
ATTRIBUTION = {"attribute", "attributed", "attributes", "attributing", "attribution"}
BELIEF = {"think", "thinks", "thought", "believe", "believed", "believes", "belief",
          "beliefs", "assume", "assumed", "imagine", "imagined", "imagination",
          "perceive", "perceived", "interpret", "interpreted", "suspect", "suspicion",
          "suspicions", "myth", "mythology", "conspiracy", "stereotype", "stereotypes",
          "rumor", "rumors"}
SEEMING = {"seem", "seems", "seemed", "appear", "appears", "appeared"}

# Typical mean activation for each group, measured on training text.
VALUE = {"blame": -6.0, "attribution": -2.5, "belief": -1.0, "seeming": -0.6}


def step(carry, prefix, upstream: Mapping):
    """The activation at this position, from the newest token alone."""
    word = prefix.token_strings[-1].strip().lower()
    if word in BLAME:
        value = VALUE["blame"]
    elif word in ATTRIBUTION:
        value = VALUE["attribution"]
    elif word in BELIEF:
        value = VALUE["belief"]
    elif word in SEEMING:
        value = VALUE["seeming"]
    else:
        value = 0.0
    return carry, float(value)

"""Ending and completion detector for one MLP down-projection component (layers.15, #4300).

The component's activation is mostly near zero, with a heavy negative tail. The tail appears
where the text marks something as over, finished or completed, or names the point after
which something else happens: "finished", "completed", "after", "end of", "once the",
"until the", "following the". Those positions get a large negative value. Text about a
beginning, or ordinary text, stays near zero.

The program scores each token from its own word and the word just before it, with weights
fitted by least squares on training activations. Within a document, the word just before is
the previous token, and it is empty at a document's first token.
"""

READS = ()

# Words that say something is finished or completed, or name a point after which
# something happens. Strongest response on the word itself.
STRONG = {"finished", "completed", "after", "finish", "完成", "完了", "完"}
MEDIUM = {
    "finishing", "completion", "complete", "completing", "concluded", "conclude",
    "concluding", "conclusion", "closing", "done", "end", "ended", "ending", "ends",
    "passed", "pass", "successfully", "accomplished", "once",
}
WEAK = {"until", "beyond", "following", "left", "outside", "off", "since", "then", "when", "from"}
TRIGGERS = STRONG | MEDIUM | WEAK

# Words that start a time boundary: the word after one of these picks up the response.
BOUNDARY = {"after", "once", "until", "following", "beyond", "left"}
DETERMINERS = {"the", "a", "an", "its", "their", "his", "her", "this", "that", "each", "every"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = word(prefix.token_strings[-2])

    value = 0.0
    if cur in STRONG:
        value += -7.2
    elif cur in MEDIUM:
        value += -2.2
    elif cur in WEAK:
        value += -0.5
    if prev == "end" and cur == "of":
        value += -14.5  # "at the end of"
    if prev in BOUNDARY and cur in DETERMINERS:
        value += -4.7  # "after the", "once the", "until the"
    if prev in TRIGGERS and cur not in TRIGGERS:
        value += -0.9  # the word right after a trigger word
    return carry, value

"""Layer 15, MLP hidden unit 4304 (written out through down_proj).

This component is one hidden unit of layer 15's MLP: its activation is that unit's
gated value, about 1.04 times it. The unit is diffuse. No token list explains it,
and the rules here explain under 1% of its variance. They capture its clearest pattern:

- "with", "without", "having", "containing" that attach a property to a noun
  ("patients treated with", "women with", "a triangle with sides") fire strongly.
  The same word after a verb of relation or completion ("associated with",
  "compared with", "finished with", "deal with") barely fires.
- Condition words ("assuming", "suppose", "when", "where") and equals signs fire
  more weakly. Everything else is 0.

The program is stateless: it reads the current word and the word before it, and
uses WordNet to tell a noun from a verb.
"""

import wordnet

READS = ()

ATTACH = {"with", "without", "having", "containing"}
CONDITION = {"assuming", "assume", "suppose", "when", "where", "whereas"}
EQUALS = {"=", "≠", "≥", "≤"}


def _word(text):
    return text.strip().lower().lstrip("_")


def _pos(word):
    """WordNet's parts of speech for a plain word, or empty for anything else."""
    if not word.isalpha():
        return frozenset()
    return wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    before = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = _word(prefix.token_strings[-2])
    if word in ATTACH:
        pos = _pos(before)
        if "noun" in pos and "verb" not in pos:
            value = 1.0  # "women with", "triangle with"
        elif "verb" in pos and "noun" not in pos:
            value = 0.15  # "associated with", "compared with"
        else:
            value = 0.7
    elif word in CONDITION:
        value = 0.5
    elif word in EQUALS:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

"""Possession detector: the component goes negative where the text says what something has.

Component p-82af68dd layers.15.mlp.down_proj:4327 is a negative-going feature of
possession. Its activation is most negative on words of having: "has", "have", "had",
"having", and have-verbs in other languages (possess, tener, tiene, иметь, ont, 有, 具有).
It is also strongly negative on the relative possessive "whose" (and "deren", "dont"),
on the word that opens the object of a have-verb ("has a", "have no", "had its"), and
mildly negative on "with" (as in "a house with a garden"), "its", "their", "his", "her",
possessive 's, and the operators * × ^ (multiplication and powers). It is weakest after a
personal pronoun ("I have", "we had"), and near zero on auxiliaries such as "is", "was",
"been" and "will".

The program is a lookup on the current word and the word before it, with a few value
levels set to the component's mean activation in each class (fitted on the first 8192
training rows, 512 tokens each). It never looks ahead, and it carries no state.
"""

READS = ()

# Verbs of having, in English and in other languages.
HAVE = {"has", "have", "had", "having"}
# Have-verbs in other languages, and "possess".
HAVE_OTHER = {
    "possess", "tener", "tiene", "tienen", "иметь", "имеет", "ont", "avoir", "haben", "hat",
    "有", "具有",
}
# Subjects after which a have-verb is weaker: first and second person, he and she.
PERSONAL = {"i", "you", "we", "he", "she"}
# Possessive relatives: "a man whose wife", "une femme dont", "deren", "для которых".
WHOSE = {"whose", "dont", "deren", "dessen", "cuyo", "cuya"}
# "with" as in "a house with a garden", and its translations.
WITH = {"with", "mit", "con", "avec"}
# Possessive determiners.
ITS_THEIR = {"its", "their"}
# Other possessive words: his, her, possessive 's, and the Chinese and Japanese particles.
POSSESSIVE = {"his", "her", "'s", "’s", "的", "の"}
# Words that open the object of a have-verb.
OBJECT_DET = {"a", "an", "its", "their", "no", "his", "her", "the", "some", "any"}
# Verbs of containing, taking, needing and providing.
VERBS = {
    "contain", "contains", "takes", "take", "need", "needs", "require", "requires",
    "get", "gets", "got", "include", "includes", "use", "uses", "offer", "offers",
    "provide", "provides", "hold", "holds", "features", "involves",
}
# Multiplication and power operators, as in "x^2" or "a × b".
MATH = {"*", "**", "×", "^"}
# A power's closing bracket, as in "(x+1)^".
CARET_CLOSE = {")^"}
# Relative and locative words, and "using", mildly negative.
LOCATIVE = {"which", "where", "there", "under", "using"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    docs = prefix.document_ids
    same_doc = len(docs) > 1 and docs[-2] == docs[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in HAVE:
        value = -1.2 if before in PERSONAL else -4.7
    elif word in HAVE_OTHER:
        value = -4.0
    elif (before in HAVE or before in HAVE_OTHER) and word in OBJECT_DET:
        value = -4.4
    elif word in WHOSE:
        value = -10.0
    elif word in WITH:
        value = -1.9
    elif word in ITS_THEIR:
        value = -2.0
    elif word in POSSESSIVE:
        value = -0.9
    elif word in VERBS:
        value = -0.8
    elif word in MATH:
        value = -2.0
    elif word in CARET_CLOSE:
        value = -5.7
    elif word in LOCATIVE:
        value = -1.0
    else:
        value = 0.0
    return carry, value

"""Layer 15, MLP hidden unit 4337 (via down_proj component 4337), read as a
"joiner inside maths and index notation" detector.

The component's activation is almost exactly this one MLP hidden unit, which is
negative where the text joins two factors, coordinates or indices with a sign:
  * a multiplication or dimension sign placed after a number or a variable
    ("3×4", "2*x", "3 times 4", "2 x 3"), strongly negative;
  * a join between two bracketed factors or indices (")(", "][", ")*(", "*("),
    strongly negative;
  * commas inside parentheses or square brackets (coordinates, index lists,
    argument lists, dimension lists), negative, and commas after a number or
    variable, weakly negative;
  * "and" joining items, a little negative; "&&" and "__", negative.
Everything else (prose, most punctuation) sits near zero, with rare large
excursions that a token rule cannot see.

The program tracks which brackets are open (carry), so it knows whether a comma
is inside parentheses or brackets. It reads only the current token and the
previous one, plus that bracket state.
"""

READS = ()

TIMES = {"×", " ×", "*", " *", "times", " times", "x", " x"}
"""Multiplication and dimension signs."""

PAIR_JOINS = {")(", ")*(", "][", "*(", ")*", "}*"}
"""Joins between two bracketed factors or two indices."""

AMP_UNDERSCORE = {" &&", "&&", "__"}
"""Logical-and and double-underscore joins, which behave like the product joins."""


def _is_number_or_variable(token: str) -> bool:
    """True for a number or single-letter variable token, with or without a leading space."""
    t = token.strip()
    return t.isdigit() or (len(t) == 1 and t.isalpha())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        # A new document: no open brackets, no previous token.
        carry = {"doc": doc, "open": "", "prev": ""}
    inner = carry["open"][-1:] if carry["open"] else ""  # innermost open bracket
    prev = carry["prev"]
    after_number_or_variable = _is_number_or_variable(prev)

    if token in TIMES:
        value = -1.4 if after_number_or_variable else -0.3
    elif token in PAIR_JOINS:
        value = -1.9
    elif token in AMP_UNDERSCORE:
        value = -0.9
    elif token == ",":
        if inner == "(":
            value = -1.4
        elif inner in ("[", "{"):
            value = -0.7
        else:
            value = -0.4 if after_number_or_variable else -0.1
    elif token == " and":
        value = -0.55
    else:
        value = 0.0

    open_brackets = carry["open"]
    for ch in token:
        if ch in "([{":
            open_brackets += ch
        elif ch in ")]}" and open_brackets:
            open_brackets = open_brackets[:-1]
    return {"doc": doc, "open": open_brackets, "prev": token}, value

"""Explains layers.15.mlp.down_proj:4339, a weak, diffuse readout of layer 15's MLP.

Its activation is a dense projection of the MLP hidden state (std about 0.31, mean about 0.04),
and it does almost nothing to the output (switching it off changes next-token KL by about 2e-6).
Nothing simple explains most of its variance. This program captures the two clearest effects:

1. Position in the document: the second token of a document (position 1) is strongly negative,
   with a decaying negative tail over the first few tokens; the first token is about zero.
2. Token class: chat and agent markup tokens (<|im_start|>, <think>, </tool_call>, ...) read
   positive; clause-opening connectives and prepositions (For, Thus, As, When, In, ...) read negative.

Everything else gets a small constant. Token identity beyond these classes adds little.
"""
import re

READS = ()

MARKUP = re.compile(r"</?\|?[A-Za-z_]+\|?>")
CONNECTIVES = {
    " For", " Therefore", " Thus", " As", " So", " Since", " When", " After", " At", " On",
    " In", " If", " Then", " Until", " Before", " Because", " While", " Although", " Whereas",
    " Upon", " Once", " From", " Of", " By", " To",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # Position within the current document: restarts when the document label changes.
    n = 0 if carry is None or carry[0] != doc else carry[1] + 1
    if n == 0:
        value = 0.0
    elif n == 1:
        value = -0.52
    elif n == 2:
        value = -0.23
    elif n == 3:
        value = -0.15
    elif n < 8:
        value = -0.08
    else:
        value = 0.03
    tok = prefix.token_strings[-1]
    if MARKUP.fullmatch(tok):
        value += 0.25
    elif tok in CONNECTIVES:
        value -= 0.2
    return (doc, n), float(value)

"""Forms of "be" (is, are, was, were, be, been, being), and "not" right after one.

This component goes strongly negative on a form of "be" that opens a verb phrase whose
main verb is still to come. It is most negative for passives and perfects, where a past
participle follows: "can be [used]", "may be [employed]", "will be [posted]",
"has been [published]", "was [measured]". It is less negative after a pronoun ("it is",
"they are"), and near zero for existential or demonstrative "be" ("there are", "this is",
"what is"). Everywhere else it sits near zero. Its sign is negative: the value is the
size of that "be" dip, not a prediction of a word.
"""

from collections.abc import Mapping

READS = ()

BE_FORMS = {"is", "are", "was", "were", "be", "been", "being"}
PAST_OR_PERFECT = {"was", "were", "been"}  # more negative than the present forms
MODALS_AND_HAVE = {"can", "may", "could", "will", "should", "must", "shall", "might", "would",
                   "cannot", "has", "have", "had"}
PRONOUNS = {"it", "they", "we", "you", "i", "he", "she", "these", "those"}
EXISTENTIAL = {"there", "here", "this", "what"}

# Typical activation for each kind of context (means measured on training text).
PASSIVE_OR_PERFECT = -5.5
AFTER_NOUN_OR_OTHER = -3.7
AFTER_PRONOUN = -2.5
EXISTENTIAL_OR_DEMONSTRATIVE = -0.7
NOT_AFTER_BE = -2.5


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in BE_FORMS:
        if prev in MODALS_AND_HAVE:
            value = PASSIVE_OR_PERFECT
        elif prev in EXISTENTIAL:
            value = EXISTENTIAL_OR_DEMONSTRATIVE
        elif prev in PRONOUNS:
            value = AFTER_PRONOUN
        else:
            value = AFTER_NOUN_OR_OTHER
        if word in PAST_OR_PERFECT:
            value -= 1.0
    elif word == "not" and prev in BE_FORMS:
        value = NOT_AFTER_BE
    else:
        value = 0.0
    return carry, float(value)

"""
Component p-82af68dd@100000/layers.15.mlp.down_proj:4347.

This is one rank-one piece of layer 15's MLP down projection. Its input direction is
almost exactly hidden unit 4347 of that MLP (weight 0.94 of its norm), so its activation is
that unit's value times about 1.1. The unit is quiet on most words and goes negative on
punctuation that opens, joins or separates items:

- opening brackets ( [ （ : about -1.0 (the bracket after a number or closing bracket is more negative, not modelled);
- operators and dashes (- -- | / + __ * &): about -0.6, or -0.8 inside brackets;
- commas, semicolons and colons: about -0.2 in running text, but about -1.1 inside
  brackets, where they separate list items.

The program tracks bracket depth within each document (reset at a document change) and
predicts these class means. Everything else is predicted as 0. It explains about 2% of the
variance: most of the unit's variance is on ordinary word tokens, whose sign depends on
context this rule does not model.
"""

READS = ()

OPENERS = {"(", "[", "（", "［"}
OPERATORS = {"-", "–", "--", "|", "/", "//", "+", "__", "*", "&"}
SEPARATORS = {",", ";", ":", "，"}
BRACKETS_IN = "([{（［"
BRACKETS_OUT = ")]}）］"


def step(carry, prefix, upstream):
    # carry: (bracket depth so far in this document, the document's label)
    depth, doc = carry if carry is not None else (0, None)
    if prefix.document_ids[-1] != doc:
        depth = 0
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1].strip()
    inside = depth > 0
    if tok in OPENERS:
        value = -1.0
    elif tok in OPERATORS:
        value = -0.8 if inside else -0.6
    elif tok in SEPARATORS:
        value = -1.1 if inside else -0.2
    else:
        value = 0.0
    for ch in tok:
        if ch in BRACKETS_IN:
            depth += 1
        elif ch in BRACKETS_OUT:
            depth = max(0, depth - 1)
    return (depth, doc), value

"""Relative-clause openers: a negative response to "which", "who" and kin.

The component's activation is large and negative where a relative pronoun opens a
clause that modifies the noun just before it, most of all a non-restrictive one set
off by a comma ("The structure, which was ...", "Clarke, who played ..."). Other
relative words (where, que, qui, che, dont) and a/an/this after a comma (an
appositive: "Gibson, a California transplant") give smaller negative values, and
"with" a small positive one. Everything else predicts 0.

Only the current token and the one before it (within the same document) are read.
"""

READS = ()

WH_RELATIVES = {"which", "who", "whom", "whose"}
OTHER_RELATIVES = {"where", "que", "qui", "che", "dont"}
DETERMINERS = {"a", "an", "this"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    after_comma = before == ","
    if word in WH_RELATIVES:
        value = -3.3 if after_comma else -1.2
    elif word in OTHER_RELATIVES:
        value = -0.2
    elif word in DETERMINERS and after_comma:
        value = -0.2
    elif word == "with":
        value = 0.2
    else:
        value = 0.0
    return carry, value
